800;cursor:pointer;color:#044a9e}.hidden{display:none}@media(max-width:360px){main{padding:18px 15px}body{font-size:16px}h1{font-size:1.48rem}}
</style></head><body><main><header><div class="brand">🔐 SafeBank</div><p class="step" id="step">MFA setup</p></header><section id="app" aria-live="polite"></section><section class="card" aria-label="Logs"><strong>Logs</strong><p class="small">Test delivery and verification messages appear here.</p><div id="logs" class="code"></div></section></main>
<script nonce="${nonce}">
(()=>{"use strict";let csrf="";const app=document.getElementById("app"),step=document.getElementById("step"),logs=document.getElementById("logs");
const log=(label,value)=>{const line=label+(value===undefined?"":": "+(Array.isArray(value)?value.join(", "):value));console.log(line);logs.textContent+=(logs.textContent?"\\n":"")+line};
function esc(v){const d=document.createElement("div");d.textContent=String(v);return d.innerHTML}
function set(label,html){step.textContent=label;app.innerHTML=html}
async function api(path,data){const r=await fetch(path,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:JSON.stringify(data||{})});const x=await r.json().catch(()=>({ok:false,message:"Please try again."}));if(r.status===401){csrf="";signin("Your session ended. Please sign in again.")}return x}
